update public.careers set title_en = 'Postdoctoral Researcher', intro_en = 'The Postdoctoral Researcher is an advanced research position that leads, develops and strengthens IEEF''s research agenda in energy economics, finance and public policy.', qualifications_en = array['Based in Bandung.', 'PhD in Economics, Finance, Management, Energy, Public Policy or a related field.', 'Previous project and research experience is an advantage.', 'Able to carry out economic and financial analysis of energy projects using at least one of: Input-Output Analysis, Real Option Valuation, Project Valuation, Techno-Economic Modelling, Monte Carlo Simulation, LCOE Analysis, Optimization Modelling or Data Analytics.', 'Familiar with Canva, Microsoft Office, social media and analytical tools for economics, energy and finance such as Excel, Stata, SPSS, EViews, R, Python, Power BI, Tableau, Bloomberg, Trading Economics, World Bank Data, IEA Statistics or other data platforms.', 'Good written and verbal communication in Bahasa Indonesia and English.', 'Thorough, proactive, with strong academic leadership and the ability to work in a multidisciplinary research team.']::text[], responsibilities_en = array['Lead and carry out research and projects in energy economics, finance and public policy, from concept to reporting.', 'Develop economic and energy policy models that support IEEF''s strategic recommendations to national and international partners.', 'Contribute to policy briefs, research reports, working papers and scientific publications such as journal articles and conference papers.', 'Supervise or mentor research assistants, interns and junior researchers.', 'Represent IEEF in academic and energy policy forums, including discussions, seminars, FGDs, workshops, conferences and external collaborations.', 'Support the development of research proposals, concept notes, methodological frameworks and collaboration with strategic partners.']::text[], notes_en = '{}'::text[] where slug = 'post-doctoral';
update public.careers set title_en = 'Research Associate', intro_en = 'SBM ITB and the Institute for Energy, Economics & Finance (IEEF) invite academics and researchers to contribute to strategic research in Energy Economics and Finance.

This position reports directly to Ir. Dzikri Firmansyah Hakam, S.T., Pg.Dip., M.Sc., Ph.D., CFP®, and is intended for candidates with a strong academic background and a record of internationally reputable publications.', qualifications_en = array['PhD in a relevant field.', 'At least one Q1 publication as first author in the last five years.', 'Expertise in Energy Economics and Finance.', 'Able to work independently and to targets.']::text[], responsibilities_en = array['Conduct research in energy economics and finance.', 'Contribute to scientific publications and policy briefs.', 'Take part in research discussions and strategic collaborations.', 'Deliver measurable research output targets.']::text[], notes_en = array['Period: April to November 2026.', 'Open until the position is filled.', 'Join us and help drive research that matters for Indonesia''s energy transition.']::text[] where slug = 'research-associate';
update public.careers set title_en = 'Research Assistant', intro_en = 'The Research Assistant supports research, analysis and study preparation in economics, energy, finance and public policy. The role suits candidates who want to learn more about strategic issues such as the energy transition, sustainable finance, energy sector investment, policy analysis and data-driven research. Research Assistants work with senior researchers and a multidisciplinary team on data collection, analysis, report writing and research and institutional communication materials.', qualifications_en = array['Based in Bandung.', 'Bachelor''s or master''s graduate, or final-year student, in Economics, Finance, Management, Energy, Public Policy, Industrial Engineering, Statistics or a related field.', 'Previous project and research experience is an advantage.', 'Able to carry out analysis under senior supervision using one of: Input-Output Analysis, Real Option Valuation, Project Valuation, Techno-Economic Modelling, Monte Carlo Simulation, LCOE Analysis, Optimization Modelling or Data Analytics.', 'Familiar with Canva, Microsoft Office, social media and analytical tools for economics, energy and finance such as Excel, Stata, SPSS, EViews, R, Python, Power BI, Tableau, Bloomberg, Trading Economics, World Bank Data, IEA Statistics or other data platforms.', 'Good written and verbal communication in Bahasa Indonesia and English.', 'Thorough, proactive and able to work in a multidisciplinary research team.']::text[], responsibilities_en = array['Carry out research and projects in energy economics, finance and public policy, including data collection, analysis and reporting.', 'Conduct economic and financial analysis in the energy sector.', 'Contribute to presentations, policy briefs and scientific publications with the research team.', 'Take part in IEEF internal activities such as workshops, research discussions and multidisciplinary collaboration.']::text[], notes_en = '{}'::text[] where slug = 'research-assistant';
update public.careers set title_en = 'Internship', intro_en = 'IEEF offers students with a strong interest in learning and growing the chance to take part directly in research on economics, energy, finance and public policy. The internship is for candidates who want to understand strategic issues such as the energy transition, sustainable finance, economic policy, data analysis and evidence-based policy research.', qualifications_en = array['Based in Bandung.', 'Current undergraduate student in at least the 4th semester, or current master''s student.', 'Strong interest in research, economics, energy, finance and public policy.', 'Willing to learn and take part in academic and policy research.', 'Able to analyse data, search the literature and write academic texts.', 'Familiar with Microsoft Office or Google Workspace, Canva, social media and analytical tools for economics, energy and finance.', 'Good written and verbal communication in Bahasa Indonesia and English.', 'Thorough, proactive, responsible and able to work in a multidisciplinary team.', 'Curious about national and global strategic issues, especially the energy transition, economic development and sustainable finance.']::text[], responsibilities_en = array['Support the research team in collecting, processing and analysing quantitative and qualitative data.', 'Help prepare literature reviews, policy briefs, research reports and academic publications.', 'Carry out desk research on economics, energy, finance, sustainable development and public policy.', 'Help with data visualisation, charts, tables and research presentation materials.', 'Help coordinate project activities, including document preparation, minutes and technical administrative support.', 'Support activity and project reports and research communication materials.', 'Contribute to internal discussions to strengthen the quality of analysis and policy recommendations.']::text[], notes_en = '{}'::text[] where slug = 'internship-program';
